<?php

namespace Database\Seeders;

use Database\Seeders\Support\SeedContext;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use RuntimeException;

/**
 * Builds the hospital dataset. Choose the size with SEED_PROFILE (small | performance)
 * and the randomness with SEED_RANDOM_SEED. See docs/database-seeding.md.
 *
 * The seeders share one SeedContext and must run together, in this order,
 * because each one uses the IDs generated by the ones before it.
 */
class DatabaseSeeder extends Seeder
{
    private const TABLES = [
        'departments', 'users', 'doctors', 'patients', 'medicines', 'rooms', 'appointments', 'medical_records',
        'prescriptions', 'prescription_items', 'admissions', 'bills', 'bill_items', 'payments',
    ];

    public function run(): void
    {
        $this->ensureNotAlreadySeeded();

        $ctx = SeedContext::fromConfig();
        $this->container->instance(SeedContext::class, $ctx);
        $this->command->info("Seeding profile '{$ctx->profileName}' with random seed {$ctx->seed} (reference date ".config('seeding.reference_date').')');

        // One transaction: either the whole dataset is created or nothing is.
        DB::transaction(fn () => $this->call([
            DepartmentSeeder::class,
            UserSeeder::class,
            DoctorSeeder::class,
            PatientSeeder::class,
            MedicineSeeder::class,
            RoomSeeder::class,
            AppointmentSeeder::class,
            MedicalRecordSeeder::class,
            PrescriptionSeeder::class,
            PrescriptionItemSeeder::class,
            AdmissionSeeder::class,
            BillSeeder::class,
            BillItemSeeder::class,
            PaymentSeeder::class,
        ]));

        // Fresh planner statistics (and cleanup of the dead tuples left by the bill-total UPDATE),
        // so EXPLAIN shows realistic plans immediately. VACUUM cannot run inside a transaction.
        $this->command->info('Running VACUUM ANALYZE...');
        foreach (self::TABLES as $table) {
            DB::statement("VACUUM ANALYZE {$table}");
        }

        $this->command->info('Peak PHP memory: '.round(memory_get_peak_usage(true) / 1048576).' MB');
    }

    /**
     * Seeded usernames look like "first.last123". API-created ones never contain a dot,
     * so this detects a previous seed run without touching or deleting anything.
     */
    private function ensureNotAlreadySeeded(): void
    {
        if (DB::table('users')->whereRaw("username ~ '^[a-z]+\\.[a-z]+[0-9]+$'")->exists()) {
            throw new RuntimeException(
                'Seed data already exists. To rebuild it in development, run: php artisan migrate:fresh --seed '
                .'(this drops ALL tables and data). See docs/database-seeding.md.'
            );
        }
    }
}
